const j = items[0].json || {};
const body = j.body || j;
const chatId = String(body.chatId || '').trim();
const text = String(body.text || '').trim();
if (!chatId) throw new Error('chatId required');
if (!text) throw new Error('text required');
const botToken = $env.TELEGRAM_NOTIFY_BOT_TOKEN || '';
if (!botToken) throw new Error('TELEGRAM_NOTIFY_BOT_TOKEN is not set');
const base = String($env.TELEGRAM_API_BASE || 'https://api.telegram.org').replace(/\/$/, '');
const proxyToken = base.includes('api.telegram.org') ? '' : String($env.GEMINI_PROXY_TOKEN || '');
return [{
  json: {
    chatId,
    text,
    url: base + '/bot' + botToken + '/sendMessage',
    proxyToken,
    menteeLabel: body.menteeLabel || '',
    title: body.title || '',
  }
}];

const res = items[0].json;
if (res.ok === true) {
  return [{ json: { ok: true, via: 'n8n-telegram-notify' } }];
}
return [{ json: { ok: false, error: res.description || JSON.stringify(res).slice(0, 400) } }];
